mapper.select:
select bdsc.id, to_char(bdsc.month,'yyyy-MM') as month, bdsc.dept_name, bdsc.platform_name, bdsc.site, bdsc.shop_name, bdsc.charge_name, bdsc.combination from bi_data_source_cost bdsc
and to_char(bdsc.month,'yyyy-MM') = #{params.month}
and bdsc.shop_name like concat('%',#{params.shopName},'%')
${params.permissionSql }
order by bdsc.month,bdsc.id

SELECT bdsc.${groupName} AS name,
       bdscd.cost_type,
       sum(COALESCE(bdscd.cost_value,0)) as cost_value
FROM bi_data_source_cost AS bdsc
LEFT JOIN bi_data_source_cost_detail AS bdscd ON bdsc.id = bdscd.cost_id
WHERE bdscd.cost_type IS NOT NULL
AND bdsc.month = #{month}
/*部门*/

    AND bdsc.dept_id IN

        #{deptId}


/*平台*/

    AND bdsc.platform_name IN

        #{platform}


/*站点*/

    AND bdsc.site IN

        #{site}



/*店铺*/

    AND bdsc.shop_no IN

        #{shopNo}


/**
  成本类型
 */

    AND  bdscd.cost_type IN

        #{item}


/*用户id*/

    AND bdscd.charge_id IN

        #{userId}




    #{params.permissionSql}

GROUP BY bdsc.${groupName},cost_type

SELECT bdsc.month AS groupDate,
bdscd.cost_type AS costType,
sum(COALESCE(bdscd.cost_value,0)) as costValue
FROM bi_data_source_cost AS bdsc
LEFT JOIN bi_data_source_cost_detail AS bdscd ON bdsc.id = bdscd.cost_id
WHERE bdscd.cost_type IS NOT NULL
/**
时间
*/

    AND bdsc.month >= #{params.startTime}


    AND bdsc.month  <=  #{params.endTime}

/*部门*/

    AND bdsc.dept_id IN

        #{deptId}


/*平台*/

    AND bdsc.platform_name IN

        #{platform}


/*站点*/

    AND bdsc.site IN

        #{site}



/*店铺*/

    AND bdsc.shop_no IN

        #{shopNo}


/**
成本类型
*/

    AND  bdscd.cost_type IN

        #{item}


/*用户id*/

    AND bdscd.charge_id IN

        #{userId}




    #{params.permissionSql}

GROUP BY bdsc.month,cost_type
